aize","label":"maize"},{"id":"desk","label":"desk"},{"id":"hen","label":"hen"}],"options":[{"id":"maize-picture","label":"A maize cob"},{"id":"desk-picture","label":"A school desk"},{"id":"hen-picture","label":"A hen"}],"inputKind":"choice"}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.reading-passage-001","schemaVersion":"1.0.1"},"component":{"componentId":"reading-passage","componentVersion":"1.0.0"},"prompt":{"default":"Read about a morning at the school garden."},"props":{"title":"The school garden","instructions":"Read the passage aloud or quietly. Retell one thing that happened.","body":"On Monday morning, Akinyi and her class watered the sukuma wiki in the school garden. They noticed a small bird near the fence. After watering, the learners returned the cans to the store.","inputKind":"none","presentation":{"canvas":{"label":"Reading passage","description":"A clear space for reading the short passage."}}}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.sentence-builder-001","schemaVersion":"1.0.1"},"component":{"componentId":"sentence-builder","componentVersion":"1.0.0"},"prompt":{"default":"Build a sentence about the goat."},"props":{"title":"Put the words in order","instructions":"Arrange the word cards to make a sentence that makes sense.","items":[{"id":"the","label":"The"},{"id":"goat","label":"goat"},{"id":"eats","label":"eats"},{"id":"grass","label":"grass."}],"inputKind":"choice","inputLabel":"Sentence order"}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.handwriting-trace-001","schemaVersion":"1.0.1"},"component":{"componentId":"handwriting-trace","componentVersion":"1.0.0"},"prompt":{"default":"Trace the letter M, then write it once on your own."},"props":{"title":"Trace M for mango","instructions":"Follow the letter shape with your finger or stylus. Then practise it in the space.","body":"Use a gentle grip and start at the top of the letter.","inputKind":"none","presentation":{"canvas":{"label":"Handwriting practice area","description":"A blank space for tracing and writing."}}}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.rich-text-content-001","schemaVersion":"1.0.1"},"component":{"componentId":"rich-text-content","componentVersion":"1.0.0"},"prompt":{"default":"Explore the parts of a healthy plant."},"props":{"title":"A plant has different parts","instructions":"Read the short notes and point to each part on a real plant if one is nearby.","body":"Roots hold a plant in the soil. The stem supports the plant. Leaves help the plant make food. A flower can grow into a fruit.","steps":["Read the notes.","Find a leaf or stem safely.","Tell a partner one job of a plant part."],"inputKind":"none"}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.single-choice-001","schemaVersion":"1.0.1"},"component":{"componentId":"single-choice","componentVersion":"1.0.0"},"prompt":{"default":"Which shape has three sides?"},"props":{"title":"Shapes in our surroundings","instructions":"Choose one shape, then look for a similar shape around the classroom.","options":[{"id":"triangle","label":"Triangle"},{"id":"square","label":"Square"},{"id":"circle","label":"Circle"}],"inputKind":"choice","inputLabel":"Shape with three sides"}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.fill-gap-001","schemaVersion":"1.0.1"},"component":{"componentId":"fill-gap","componentVersion":"1.0.0"},"prompt":{"default":"Complete the sentence: A cow has ___ legs."},"props":{"title":"Complete the animal fact","instructions":"Type the number that completes the sentence.","body":"Say the whole sentence aloud after you fill the gap.","inputKind":"numeric","inputLabel":"Number of legs","inputPlaceholder":"Type a number","inputMaxLength":1}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.worked-example-001","schemaVersion":"1.0.1"},"component":{"componentId":"worked-example","componentVersion":"1.0.0"},"prompt":{"default":"Follow the steps to add 6 and 3."},"props":{"title":"Adding two small numbers","instructions":"Read each step, then use counters to show the same idea.","steps":["Start with 6 counters.","Add 3 more counters.","Count all the counters together."],"body":"You can use beans, bottle tops, or small stones as counters.","inputKind":"numeric","inputLabel":"Total counters"}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.number-line-001","schemaVersion":"1.0.1"},"component":{"componentId":"number-line","componentVersion":"1.0.0"},"prompt":{"default":"Start at 4 and make two jumps forward."},"props":{"title":"Jumps on a number line","instructions":"Move along the line one step at a time. Record where you stop.","list":["0","1","2","3","4","5","6","7","8"],"inputKind":"numeric","inputLabel":"Number where you stop","presentation":{"canvas":{"label":"Number-line movement area","description":"A horizontal number line from 0 to 8."}}}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.fraction-manipulative-001","schemaVersion":"1.0.1"},"component":{"componentId":"fraction-manipulative","componentVersion":"1.0.0"},"prompt":{"default":"Show one half using the chapati pieces."},"props":{"title":"Sharing a chapati fairly","instructions":"Use the pieces to show two equal parts. Describe one part.","body":"Imagine sharing one round chapati equally between two learners.","items":[{"id":"piece-a","label":"Part A"},{"id":"piece-b","label":"Part B"}],"inputKind":"choice","inputLabel":"Fraction shown","options":[{"id":"one-half","label":"One half"},{"id":"one-third","label":"One third"},{"id":"one-whole","label":"One whole"}]}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.measurement-lab-001","schemaVersion":"1.0.1"},"component":{"componentId":"measurement-lab","componentVersion":"1.0.0"},"prompt":{"default":"Compare the lengths of a pencil and a book."},"props":{"title":"Measure classroom objects","instructions":"Use a ruler or hand spans. Record a measurement and compare the two objects.","steps":["Place the ruler at the edge.","Read the length in centimetres.","Say which object is longer."],"body":"Choose a pencil and a small exercise book from your desk.","inputKind":"numeric","inputLabel":"Pencil length in centimetres","inputPlaceholder":"For example, 15","inputMaxLength":2}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.equation-builder-001","schemaVersion":"1.0.1"},"component":{"componentId":"equation-builder","componentVersion":"1.0.0"},"prompt":{"default":"Build a number sentence for 5 birds and 2 more birds."},"props":{"title":"Build an addition sentence","instructions":"Arrange the cards to show the story with numbers and a plus sign.","body":"Draw five birds, then draw two more if that helps you think.","items":[{"id":"five","label":"5"},{"id":"plus","label":"+"},{"id":"two","label":"2"},{"id":"equals","label":"="},{"id":"seven","label":"7"}],"inputKind":"choice","inputLabel":"Number sentence order"}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.data-table-chart-001","schemaVersion":"1.0.1"},"component":{"componentId":"data-table-chart","componentVersion":"1.0.0"},"prompt":{"default":"Read the class fruit table and describe the biggest group."},"props":{"title":"Fruit brought to class","instructions":"Read each row. Use the table to compare the numbers.","table":{"columns":["Fruit","Number of learners"],"rows":[["Banana","6"],["Mango","4"],["Orange","3"]]},"inputKind":"text","inputLabel":"Fruit with the largest group","inputPlaceholder":"Type a fruit name","inputMaxLength":12}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.labelled-science-diagram-001","schemaVersion":"1.0.1"},"component":{"componentId":"labelled-science-diagram","componentVersion":"1.0.0"},"prompt":{"default":"Explore the parts of a bean seedling."},"props":{"title":"Label a young plant","instructions":"Choose a label and place it beside the part it names.","body":"A bean seedling has roots below the soil, a stem, and small leaves above the soil.","items":[{"id":"roots","label":"Roots"},{"id":"stem","label":"Stem"},{"id":"leaves","label":"Leaves"}],"inputKind":"choice","presentation":{"canvas":{"label":"Bean seedling diagram","description":"A simple diagram area for placing plant-part labels."}}}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.observation-table-001","schemaVersion":"1.0.1"},"component":{"componentId":"observation-table","componentVersion":"1.0.0"},"prompt":{"default":"Record what you notice about two leaves."},"props":{"title":"Leaf observation","instructions":"Look closely without picking a living leaf. Record colour and texture.","table":{"columns":["Leaf","Colour","Texture"],"rows":[["Leaf A","",""],["Leaf B","",""]]},"inputKind":"text","inputLabel":"Your observation","inputPlaceholder":"For example, green and smooth","inputMaxLength":40}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.virtual-lab-001","schemaVersion":"1.0.1"},"component":{"componentId":"virtual-lab","componentVersion":"1.0.0"},"prompt":{"default":"Explore what happens when a shadow is made with a torch."},"props":{"title":"Light and shadow","instructions":"Move the object between the torch and the screen. Describe the shadow.","steps":["Place the object near the torch.","Place it near the screen.","Compare the two shadows."],"options":[{"id":"larger","label":"The shadow looks larger"},{"id":"smaller","label":"The shadow looks smaller"},{"id":"same","label":"The shadow looks the same"}],"inputKind":"choice","inputLabel":"What did you observe?"}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.glb-3d-model-viewer-001","schemaVersion":"1.0.1"},"component":{"componentId":"glb-3d-model-viewer","componentVersion":"1.0.0"},"prompt":{"default":"Explore a 3D model of a bicycle and name two visible parts."},"props":{"title":"Turn and inspect a bicycle","instructions":"Rotate the model if available. Look at the wheels, seat, and handlebar.","body":"Static fallback: A bicycle has two round wheels, a seat, pedals, and handlebars. Point to two parts in the picture or model.","steps":["Look at the whole bicycle.","Find the two wheels.","Name another part you can see."],"inputKind":"text","inputLabel":"A bicycle part I can see","inputPlaceholder":"Type one part","inputMaxLength":20,"presentation":{"model":{"label":"Bicycle 3D model","description":"An optional rotatable bicycle model; use the text fallback if unavailable."}}}},{"identity":{"sceneId":"ken-cbc-lower-primary.math-science.specimen-3d-explorer-001","schemaVersion":"1.0.1"},"component":{"componentId":"specimen-3d-explorer","componentVersion":"1.0.0"},"prompt":{"default":"Explore a 3D model of a maize cob and describe its surface."},"props":{"title":"Inspect a maize cob","instructions":"Rotate or zoom the specimen if available. Observe its shape and texture.","body":"Static fallback: A maize cob is long and has many kernels arranged in rows. Describe one feature you notice.","steps":["Look at the shape.","Look for rows of kernels.","Share one observation."],"inputKind":"text","inputLabel":"Feature I noticed","inputPlaceholder":"Type a short description","inputMaxLength":40,"presentation":{"model":{"label":"Maize cob specimen","description":"An optional rotatable maize cob model; use the text fallback if unavailable."}}}},{"identity":{"sceneId":"ken-cbc-g1-mathematics.trace-curved-line-001","schemaVersion":"1.0.1"},"component":{"componentId":"trace-construct","componentVersion":"1.0.0"},"purpose":"instruction","prompt":{"default":"Choose the curved line."},"props":{"mode":"trace-path","targets":[{"id":"curved-line","label":"〰","accessibleDescription":"A curved line"},{"id":"straight-line","label":"—","accessibleDescription":"A straight line"}],"selectionCount":1,"instruction":{"default":"Tap the line that bends."},"accessibility":{"selectionLabel":{"default":"Line choices"}}},"evidenceClaims":[{"claimId":"g1-mathematics-identifies-curved-line","description":{"default":"Identifies a curved line from familiar line choices."},"evidenceTypes":["observation"]}],"completion":{"completionRuleId":"component-defined","kind":"component-defined"},"tutorPermissions":[],"assets":{"manifestId":"g1-curved-line-assets","assets":[]}},{"identity":{"sceneId":"ken-cbc-g1-science-health.classify-food-001","schemaVersion":"1.0.1"},"component":{"componentId":"authored-interaction","componentVersion":"1.0.0"},"purpose":"instruction","prompt":{"default":"Classify each food as a fruit or a vegetable."},"props":{"mode":"classify","instruction":"Tap a food, then tap its group.","items":[{"id":"mango","label":"Mango","accessibleDescription":"A mango"},{"id":"carrot","label":"Carrot","accessibleDescription":"A carrot"}],"groups":[{"id":"fruit","label":"Fruit"},{"id":"vegetable","label":"Vegetable"}]},"evidenceClaims":[{"claimId":"g1-science-health-classifies-food","description":{"default":"Classifies familiar foods into fruit and vegetable groups."},"evidenceTypes":["observation"]}],"completion":{"completionRuleId":"component-defined","kind":"component-defined"},"tutorPermissions":[],"assets":{"manifestId":"g1-classify-food-assets","assets":[]}},{"identity":{"sceneId":"ken-cbc-g1-english.comprehension-questions-school-garden-001","schemaVersion":"1.0.1"},"component":{"componentId":"comprehension-questions","componentVersion":"1.0.0"},"prompt":{"default":"Read about Akinyi helping in the school garden, then share what you understand."},"props":{"title":"Akinyi in the school garden","instructions":"Read the short passage and answer each question in your own words.","body":"Akinyi carries a small watering can to the school garden. She waters the sukuma wiki and checks that the soil is moist. Her class will use the vegetables for a healthy lunch.","list":["Who carries the watering can?","Which vegetable does Akinyi water?","Why does the class grow vegetables?"],"inputKind":"text","inputLabel":"Write one answer at a time","inputPlaceholder":"Use a short sentence","inputMaxLength":160}},{"identity":{"sceneId":"ken-cbc-g1-business-life-skills.budget-planner-school-snack-001","schemaVersion":"1.0.1"},"component":{"componentId":"budget-planner","componentVersion":"1.0.0"},"prompt":{"default":"Plan how to use a small amount of money for a healthy school snack."},"props":{"title":"A small snack budget","instructions":"Look at the snack choices and plan how you would spend carefully. Talk about your choice with a trusted adult or partner.","body":"Imagine you have 20 shillings for a school snack. You may choose fruit, water, or another food available at your school.","options":[{"id":"banana-water","label":"A banana and water","description":"A simple snack and a drink."},{"id":"fruit-only","label":"Fruit only","description":"Choose one fruit that fits your budget."},{"id":"save-some","label":"Save some money","description":"Choose less now and keep some for another need."}],"inputKind":"choice","inputLabel":"My spending plan"}},{"identity":{"sceneId":"ken-cbc-g1-business-life-skills.nutrition-plate-builder-healthy-lunch-001","schemaVersion":"1.0.1"},"component":{"componentId":"nutrition-plate-builder","componentVersion":"1.0.0"},"prompt":{"default":"Build a colourful plate for a healthy Kenyan lunch."},"props":{"title":"A healthy lunch plate","instructions":"Choose foods from different groups and describe how your plate has variety. Use foods that are familiar and available to your family.","items":[{"id":"ugali","label":"Ugali","description":"A staple food that gives energy."},{"id":"beans","label":"Beans","description":"A food that helps the body grow."},{"id":"sukuma-wiki","label":"Sukuma wiki","description":"A leafy vegetable."},{"id":"mango","label":"Mango","description":"A fruit."},{"id":"water","label":"Clean water","description":"A drink for the body."}],"inputKind":"choice","inputLabel":"Food I would add next"}},{"identity":{"sceneId":"ken-cbc-g1-business-life-skills.health-anatomy-diagram.body-parts-001","schemaVersion":"1.0.1"},"component":{"componentId":"health-anatomy-diagram","componentVersion":"1.0.0"},"prompt":{"default":"Explore a simple body diagram and name parts that help us move and sense."},"props":{"title":"My body helps me learn","instructions":"Point to or select a body part, then describe one everyday job it helps you do. Do not share private health details.","body":"Hands can hold a pencil, eyes can look at a book, ears can listen, and feet can help us walk.","items":[{"id":"eyes","label":"Eyes","description":"Help us see."},{"id":"ears","label":"Ears","description":"Help us hear."},{"id":"hands","label":"Hands","description":"Help us hold and make things."},{"id":"feet","label":"Feet","description":"Help us stand and move."}],"inputKind":"choice","inputLabel":"Body part I chose","presentation":{"canvas":{"label":"Simple body diagram","description":"A large, high-contrast diagram with text labels; the written descriptions are a complete fallback."}}}},{"identity":{"sceneId":"ken-cbc-g1-business-life-skills.safety-decision-scenario-road-crossing-001","schemaVersion":"1.0.1"},"component":{"componentId":"safety-decision-scenario","componentVersion":"1.0.0"},"prompt":{"default":"Think about a safe way to cross a road near school."},"props":{"title":"A safe journey home","instructions":"Read the situation, choose a response, and explain who can help you stay safe. Never practise near moving traffic.","body":"You are walking home from school and need to cross a busy road. A trusted adult or crossing area is nearby.","options":[{"id":"use-crossing","label":"Use the crossing with help","description":"Stop, look, listen, and cross with a trusted adult when possible."},{"id":"wait-safely","label":"Wait in a safe place","description":"Stay away from the road edge until it is safe to cross."},{"id":"ask-adult","label":"Ask a trusted adult","description":"Ask a teacher, caregiver, or other trusted adult for help."}],"inputKind":"choice","inputLabel":"My safety choice"}},{"identity":{"sceneId":"ken-cbc-g1-busines