es":["answer"]}],"grader":{"graderId":"kitabu.sealed-numeric-answer","graderVersion":"1.0.0","mode":"exact"},"completion":{"completionRuleId":"submit-response","kind":"submitted","requiredClaimIds":["g2-mathematics-counts-apples"]},"tutorPermissions":[],"assets":{"manifestId":"ken-cbc-g2-mathematics.count-apples-001.assets","assets":[]},"attemptPolicy":{"maxAttempts":2,"feedbackTiming":"after-attempts","revealAnswer":"never"}},{"identity":{"sceneId":"ken-cbc-g2-mathematics.order-numbers-001","schemaVersion":"1.0.1"},"component":{"componentId":"classify-sort-match-rank","componentVersion":"1.0.0"},"purpose":"practice","prompt":{"default":"Order 12, 5, and 9 from smallest to largest."},"props":{"mode":"ranked-list","items":[{"id":"number-12","label":"12","value":12,"accessibleDescription":"twelve"},{"id":"number-5","label":"5","value":5,"accessibleDescription":"five"},{"id":"number-9","label":"9","value":9,"accessibleDescription":"nine"}],"orderingRules":{"direction":"ascending"},"allowMultiplePlacements":false,"unplacedPolicy":"all-items-required","layout":{"orientation":"vertical","showPositionNumbers":true},"shuffleSeed":"g2-order-numbers-001","explanationPolicy":{"required":false},"keyboardMoveModel":"move-buttons"},"evidenceClaims":[{"claimId":"g2-mathematics-orders-numbers","description":{"default":"Orders three numbers from smallest to largest."},"evidenceTypes":["answer"]}],"grader":{"graderId":"ordered-item-ids","graderVersion":"1.0.0","mode":"exact"},"completion":{"completionRuleId":"ordered-list-complete","kind":"evidence-claims-met","requiredClaimIds":["g2-mathematics-orders-numbers"]},"tutorPermissions":[],"assets":{"manifestId":"g2-order-numbers-assets","assets":[]},"attemptPolicy":{"maxAttempts":2,"feedbackTiming":"on-submit","revealAnswer":"never"}},{"identity":{"sceneId":"ken-cbc-g2-art.scribble-sign-doodle-canvas-community-market-001","schemaVersion":"1.0.1"},"component":{"componentId":"scribble-sign-doodle-canvas","componentVersion":"1.0.0"},"prompt":{"default":"Make a friendly sign for a Kenyan community market stall."},"props":{"title":"Market stall sign","instructions":"Scribble, sign, or doodle a bright sign for a fruit stall. Add a picture and a few words.","list":["Draw one fruit sold at the stall.","Add the stall name or a welcoming phrase.","Use lines, shapes, or colours to make the sign easy to see."],"inputKind":"none","presentation":{"canvas":{"label":"Doodle canvas","description":"A free drawing area for a market-stall sign."}}}},{"identity":{"sceneId":"ken-cbc-g2-business-life-skills.crop-life-cycle-maize-001","schemaVersion":"1.0.1"},"component":{"componentId":"crop-life-cycle","componentVersion":"1.0.0"},"prompt":{"default":"Put the stages of a maize plant life cycle in an order that makes sense."},"props":{"title":"From maize seed to cob","instructions":"Arrange the stages and describe one change you notice as the maize grows.","items":[{"id":"seed","label":"Seed in the soil"},{"id":"sprout","label":"Small sprout"},{"id":"plant","label":"Tall maize plant"},{"id":"cob","label":"Maize cob with kernels"}],"inputKind":"text","inputLabel":"One change I notice","inputPlaceholder":"Write a short observation","inputMaxLength":100,"presentation":{"canvas":{"label":"Maize life-cycle picture area","description":"A clear, labelled area for arranging the stages; the text cards remain available if the picture is not shown."}}}},{"identity":{"sceneId":"ken-cbc-g2-business-life-skills.drama-roleplay.market-greeting-001","schemaVersion":"1.0.1"},"component":{"componentId":"drama-roleplay","componentVersion":"1.0.0"},"prompt":{"default":"Practise a respectful greeting between a customer and a market seller."},"props":{"title":"A friendly market greeting","instructions":"Choose a role or read both parts with a partner. Use a clear voice, listen carefully, and stop if anyone feels uncomfortable.","steps":["Seller: Welcome. How may I help you?","Customer: Please show me the bananas.","Seller: Here they are. Thank you for asking politely."],"options":[{"id":"seller","label":"Seller"},{"id":"customer","label":"Customer"},{"id":"reader","label":"Reader or narrator"}],"inputKind":"choice","inputLabel":"Role I will try"}},{"identity":{"sceneId":"ken-cbc-g2-business-life-skills.movement-sequence.safe-classroom-001","schemaVersion":"1.0.1"},"component":{"componentId":"movement-sequence","componentVersion":"1.0.0"},"prompt":{"default":"Follow a gentle movement sequence that can be done safely beside your desk."},"props":{"title":"Move and pause","instructions":"Make space, move gently, and keep your own comfort in mind. You may watch, use smaller movements, or stop at any time.","steps":["Stand or sit tall.","Reach both hands up if comfortable.","Circle the shoulders slowly.","Take one calm breath and pause."],"body":"Static fallback: Read each step aloud and imagine or mime the movement without leaving your place.","inputKind":"none","presentation":{"canvas":{"label":"Movement sequence cards","description":"Large step cards with simple words; the written sequence works without animation."}}}},{"identity":{"sceneId":"ken-cbc-g2-business-life-skills.emotion-regulation-checkin.calm-start-001","schemaVersion":"1.0.1"},"component":{"componentId":"emotion-regulation-checkin","componentVersion":"1.0.0"},"prompt":{"default":"Notice how you feel and choose a safe way to get ready to learn."},"props":{"title":"My calm learning check-in","instructions":"Choose a word that fits how you feel now, then choose a helpful next step. You may keep your answer private and ask a trusted adult for support.","options":[{"id":"ready","label":"Ready","description":"I can begin a learning activity."},{"id":"unsure","label":"Unsure","description":"I may need a quiet moment or a simple explanation."},{"id":"need-support","label":"Need support","description":"I can tell a trusted adult that I need help."}],"list":["Take one slow breath.","Sip water if it is available.","Ask for a quiet space or kind help."],"inputKind":"choice","inputLabel":"My check-in"}},{"identity":{"sceneId":"ken-cbc-g2-business-life-skills.lesson-flow.school-garden-project-001","schemaVersion":"1.0.1"},"component":{"componentId":"lesson-flow","componentVersion":"1.0.0"},"prompt":{"default":"Follow a short lesson flow for planting and caring for a class seed."},"props":{"title":"Our seed lesson","instructions":"Move through the lesson steps in order. Work with a teacher or caregiver and wash hands after handling soil.","steps":["Look at a dry seed.","Talk about what a seed needs.","Place a seed in prepared soil with help.","Draw or describe what you notice later."],"inputKind":"none"}},{"identity":{"sceneId":"ken-cbc-g2-business-life-skills.feedback-panel.team-garden-001","schemaVersion":"1.0.1"},"component":{"componentId":"feedback-panel","componentVersion":"1.0.0"},"prompt":{"default":"Share kind, useful feedback after working with a partner in the school garden."},"props":{"title":"Helpful partner feedback","instructions":"Choose a sentence starter and complete it with something you noticed. Talk about the work, not a person’s worth.","options":[{"id":"liked","label":"I liked...","description":"Name one helpful part of the work."},{"id":"noticed","label":"I noticed...","description":"Describe something you saw or heard."},{"id":"next-time","label":"Next time...","description":"Suggest one small improvement kindly."}],"inputKind":"text","inputLabel":"My feedback","inputPlaceholder":"Complete one sentence starter","inputMaxLength":120}},{"identity":{"sceneId":"ken-cbc-g3-science.draw-annotate-canvas-maize-plant-001","schemaVersion":"1.0.1"},"component":{"componentId":"draw-annotate-canvas","componentVersion":"1.0.0"},"prompt":{"default":"Draw and label the main parts of a maize plant growing on a Kenyan farm."},"props":{"title":"Parts of a maize plant","instructions":"Sketch the plant, then add labels and arrows to show what you know.","list":["Include the roots, stem, leaves, and maize cob.","Draw an arrow from each label to the correct part.","Write one observation about how the plant grows."],"inputKind":"none","presentation":{"canvas":{"label":"Plant annotation canvas","description":"A drawing area for a maize plant and learner-made labels."}}}},{"identity":{"sceneId":"ken-cbc-g3-business-life-skills.accounting-ledger-school-garden-001","schemaVersion":"1.0.1"},"component":{"componentId":"accounting-ledger","componentVersion":"1.0.0"},"prompt":{"default":"Record simple items received and used in a school garden project."},"props":{"title":"School garden record","instructions":"Read the garden notes and add a short record for each item. Use words or numbers that you can explain.","body":"The class received 6 seed packets and used 2 packets in the garden. The remaining packets were stored safely.","table":{"columns":["Item","Received","Used","Note"],"rows":[["Seed packets","6","2","Stored the rest safely"],["Watering cans","2","1","The other can is in the store"]]},"inputKind":"text","inputLabel":"One record I can explain","inputPlaceholder":"Write an item and what happened","inputMaxLength":100}},{"identity":{"sceneId":"ken-cbc-g3-business-life-skills.offline-content-fallback.school-shop-001","schemaVersion":"1.0.1"},"component":{"componentId":"offline-content-fallback","componentVersion":"1.0.0"},"prompt":{"default":"Continue a simple school-shop activity when the learning device has no connection."},"props":{"title":"Learning without a connection","instructions":"Use the saved activity on the device or read the printed notes. Continue with a partner and ask a teacher if you need help.","body":"Offline fallback: A class shop has 3 pencils, 2 exercise books, and 4 rulers. Draw or list the items, then describe one way to keep the shop record neat.","steps":["Read the saved notes.","Draw or list the shop items.","Share one neat record with a partner."],"inputKind":"text","inputLabel":"My offline note","inputPlaceholder":"Write one shop item or observation","inputMaxLength":100,"presentation":{"canvas":{"label":"Saved offline activity","description":"A readable text version remains available when images or network content cannot load."}}}},{"identity":{"sceneId":"ken-cbc-g3-business-life-skills.asset-reference.maize-tools-001","schemaVersion":"1.0.1"},"component":{"componentId":"asset-reference","componentVersion":"1.0.0"},"prompt":{"default":"Look at the classroom picture or saved description of tools used to care for a maize crop."},"props":{"title":"Tools for a maize garden","instructions":"Select a tool and explain how it may be used safely. Use the text description if the picture is not available.","body":"Static fallback: A watering can carries water, a hoe helps prepare soil with adult guidance, and a basket can carry harvested maize.","items":[{"id":"watering-can","label":"Watering can","description":"Carries water to plants."},{"id":"hoe","label":"Hoe","description":"A tool used by an adult to prepare soil safely."},{"id":"basket","label":"Basket","description":"Carries produce or garden items."}],"inputKind":"choice","inputLabel":"Tool I chose","presentation":{"canvas":{"label":"Saved garden-tool picture","description":"A local, packaged picture may be shown here; the text labels and descriptions are the accessible fallback."}}}},{"identity":{"sceneId":"ken-cbc-g3-business-life-skills.evidence-capture.school-garden-observation-001","schemaVersion":"1.0.1"},"component":{"componentId":"evidence-capture","componentVersion":"1.0.0"},"prompt":{"default":"Capture a short record of what you observed in a school or home garden."},"props":{"title":"My garden observation","instructions":"Write or dictate one observation from your activity. Do not include your full name, address, phone number, or another person's private information.","body":"You can record a leaf colour, the condition of the soil, or a change you noticed. A drawing or spoken description is also useful.","list":["What did you observe?","Where was the plant or object?","What question do you still have?"],"inputKind":"text","inputLabel":"Observation record","inputPlaceholder":"Write one short observation","inputMaxLength":180,"presentation":{"canvas":{"label":"Observation note area","description":"A simple text or drawing area for learner evidence; a spoken or paper note is an acceptable fallback."}}}},{"identity":{"sceneId":"ken-cbc-g4-social-studies.map-explorer-kenya-regions-001","schemaVersion":"1.0.1"},"component":{"componentId":"map-explorer","componentVersion":"1.0.0"},"prompt":{"default":"Explore a map of Kenya and compare places near the coast, lake, and highlands."},"props":{"title":"Kenya places and regions","instructions":"Use the map view to locate the examples, then describe one difference between two places.","list":["Find Mombasa near the Indian Ocean.","Find Kisumu near Lake Victoria.","Find a highland town such as Nyeri or Eldoret.","Describe one way land or water may affect life in two places."],"inputKind":"text","inputLabel":"Compare two places","inputPlaceholder":"Write one observation","inputMaxLength":220,"presentation":{"map":{"label":"Kenya map explorer","description":"A map view for locating Kenyan places and comparing their surroundings."}}}},{"identity":{"sceneId":"ken-cbc-g5-history.history-timeline-independence-001","schemaVersion":"1.0.1"},"component":{"componentId":"history-timeline","componentVersion":"1.0.0"},"prompt":{"default":"Place key events from Kenya's journey to independence in a clear timeline."},"props":{"title":"Kenya: independence milestones","instructions":"Read the milestones, put them in time order, and add one sentence about why timelines help.","table":{"columns":["Year","Milestone"],"rows":[["1963","Kenya gained independence."],["1964","Kenya became a republic."],["2010","Kenya adopted a new Constitution."]]},"list":["Notice which event happened first.","Compare the years and the spaces between them.","Explain how a timeline shows change over time."],"inputKind":"text","inputLabel":"Your timeline reflection","inputPlaceholder":"Write one sentence","inputMaxLength":180}},{"identity":{"sceneId":"ken-cbc-g6-social-studies.primary-source-analysis-school-archive-001","schemaVersion":"1.0.1"},"component":{"componentId":"primary-source-analysis","componentVersion":"1.0.0"},"prompt":{"default":"Study a school archive note about a community clean-up and explain what it can tell us."},"props":{"title":"Reading a community archive note","instructions":"Read the source description carefully. Separate details you can observe from ideas you infer.","body":"Source description: A handwritten note in a Kisumu school archive records a Saturday clean-up near a footpath by the lake. It names the date, the clubs that joined, and the number of rubbish bags collected.","list":["Which details come directly from the note?","Who might have created this source, and why?","What question would you ask before using it as evidence?"],"inputKind":"text","inputLabel":"Write your source analysis","inputPlaceholder":"Use details from the source description","inputMaxLength":280}},{"identity":{"sceneId":"ken-cbc-g7-computer-studies.hardware-labeling-solar-lab-001","schemaVersion":"1.0.1"},"component":{"componentId":"hardware-labeling","componentVersion":"1.0.0"},"prompt":{"default":"Label the hardware in a solar-powered computer lab and describe each part's role."},"props":{"title":"Solar computer lab hardware","instructions":"Match each visible part with a useful label, then describe how it helps the learner use the computer.","items":[{"id":"screen","label":"Screen","description":"Displays words, pictures, and learning activities."},{"id":"keyboard","label":"Keyboard","description":"Lets a learner enter letters, numbers, and symbols."},{"id":"mouse","label":"Mouse or touchpad","description":"Moves the pointer and selects items."},{"id":"solar-battery","label":"Solar battery unit","description":"Stores electrical energy for the lab."}],"list":["Look for the part that displays information.","Look for the part used to type.","Identify the unit that stores energy for later use."],"inputKind":"text","inputLabel":"Describe one hardware part","inputPlaceholder":"Name the part and its role","inputMaxLength":180}},{"identity":{"sceneId":"ken-cbc-g8-computing.block-code-trace-library-counter-001","schemaVersion":"1.0.1"},"component":{"componentId":"block-code-trace","componentVersion":"1.0.0"},"prompt":{"default":"Trace a block sequence that counts books added to a classroom library."},"props":{"title":"Classroom library counter","instructions":"Follow the block descriptions in order, keep track of the changing count, and record what you notice.","items":[{"id":"start-count","label":"Start with a count","description":"The shelf begins with 2 books."},{"id":"repeat-add","label":"Repeat an action","description":"The same book-counting action happens three times."},{"id":"add-book","label":"Add one book","description":"Increase the count by one whenever a book is placed on the shelf."},{"id":"show-count","label":"Show the count","description":"Display the count after the repeated action finishes."}],"list":["Read each block description from top to bottom.","Track how the count changes after each repeated action.","Explain in words what the repeat block does."],"inputKind":"numeric","inputLabel":"Record the final count","inputPlaceholder":"Enter a number"}},{"identity":{"sceneId":"ken-cbc-g9-life-skills.digital-citizenship-scenario-class-group-001","schemaVersion":"1.0.1"},"component":{"componentId":"digital-citizenship-scenario","componentVersion":"1.0.0"},"prompt":{"default":"Choose a safe and respectful response when an unfamiliar image appears in a class group."},"props":{"title":"A thoughtful class-group response","instructions":"Read the situation, choose a response, and explain how it protects people and supports respectful communication.","body":"A learner in a school class group receives an image from an unfamiliar account. The image asks for personal details and encourages everyone to forward it quickly.","options":[{"id":"pause-check","label":"Pause and check","description":"Do not forward it; ask a trusted teacher or adult to help check the message."},{"id":"protect-privacy","label":"Protect privacy","description":"Keep personal details private and remind classmates not to share theirs."},{"id":"report-block","label":"Report and block","description":"Use the group or device safety tools if the message is unwanted or harmful."},{"id":"send-on","label":"Forward quickly","description":"Share the image with more people before checking it."}],"list":["Look for a response that protects personal information.","Consider who could help you check an unfamiliar message.","Explain how your choice shows respect for classmates."],"inputKind":"choice"}}],"assetManifest":{"manifestVersion":1,"assets":[]}}$bundle$::JSONB;
BEGIN
  SELECT u.id INTO actor_id
  FROM users u
  JOIN user_roles ur ON ur.user_id = u.id
  WHERE ur.role = 'platform_admin'::user_role
  ORDER BY u.id
  LIMIT 1;

  IF actor_id IS NULL THEN
    RAISE NOTICE 'Skipped generative UI catalogue preview seed: no platform-admin actor exists.';
    RETURN;
  END IF;

  INSERT INTO interactive_learning_bundles
    (bundle_id, revision, sha256, channel, release_id, manifest, payload, status, created_by, approved_by, approved_at)
  VALUES (
    bundle_payload->'manifest'->>'bundleId',
    bundle_payload->'manifest'->>'revision',
    bundle_payload->'manifest'->>'sha256',
    bundle_payload->'manifest'->'release'->>'channel',
    bundle_payload->'manifest'->'release'->>'releaseId',
    bundle_payload->'manifest',
    bundle_payload,
    'approved',
    actor_id,
    actor_id,
    NOW()
  )
  ON CONFLICT (bundle_id, revision) DO NOTHING;

  INSERT INTO interactive_learning_release_history (channel, bundle_id, revision, release_id, action, actor_user_id)
  SELECT
    bundle_payload->'manifest'->'release'->>'channel',
    bundle_payload->'manifest'->>'bundleId',
    bundle_payload->'manifest'->>'revision',
    bundle_payload->'manifest'->'release'->>'releaseId',
    'publish',
    actor_id
  WHERE NOT EXISTS (
    SELECT 1 FROM interactive_learning_release_history
    WHERE release_id = bundle_payload->'manifest'->'release'->>'releaseId' AND action = 'publish'
  );

  INSERT INTO interactive_learning_release_pointers (channel, bundle_id, revision, release_id, updated_by)
  VALUES (
    bundle_payload->'manifest'->'release'->>'channel',
    bundle_payload->'manifest'->>'bundleId',
    bundle_payload->'manifest'->>'revision',
    bundle_payload->'manifest'->'release'->>'releaseId',
    actor_id
  )
  ON CONFLICT (channel) DO UPDATE SET
    bundle_id = EXCLUDED.bundle_id,
    revision = EXCLUDED.revision,
    release_id = EXCLUDED.release_id,
    updated_by = EXCLUDED.updated_by,
    updated_at = NOW();
END $$;
